create or replace function private.configuracao_publica() returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_object_agg(key,value) from public.configuracoes c, lateral jsonb_each(c.dados) where c.id=true and key=any(array['empresa','whatsapp','antecedencia_min','antecedencia_max','prazo_fiado','pix_chave','pix_nome','pix_cidade','tamanhos','multiplo_pedido','frete_gratis','endereco_saida','distancia_max','recebendo_pedidos','aviso_privacidade','versao']); $$;
